const sha=v=>crypto.createHash('sha256').update(v).digest('hex');
function fail(c){throw new Error(c)}
function replaceOnce(source,needle,replacement,label){const n=source.split(needle).length-1;if(n!==1)fail('anchor_mismatch:'+label+':'+n);return source.replace(needle,replacement)}
function patchBase(source){
  if(source.includes("honartik_iticket_pretoken_prepare_v1: { operation:"))fail('base_action_already_present');
  const specOld="  honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1: { operation: 'host_action.honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1', rollback: 'host-action-v2:honartik-iticket-batch2-result-bridge-helper-refresh-v1:helper-file-rollback' },\n  host_action_v2_installer_v1:";
  const specNew="  honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1: { operation: 'host_action.honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1', rollback: 'host-action-v2:honartik-iticket-batch2-result-bridge-helper-refresh-v1:helper-file-rollback' },\n  honartik_iticket_pretoken_prepare_v1: { operation: 'host_action.honartik_iticket_pretoken_prepare_v1', rollback: 'host-action-v2:honartik-iticket-pretoken-prepare-v1:worktree-remove-branch-delete' },\n  host_action_v2_installer_v1:";
  let out=replaceOnce(source,specOld,specNew,'base_spec');
  out=replaceOnce(out,'"honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1","imotion_marketing_target_register_v1"','"honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1","honartik_iticket_pretoken_prepare_v1","imotion_marketing_target_register_v1"','base_level3');
  return out;
}
function executorBlock(){return `
const HONARTIK_ITICKET_PRETOKEN_HELPER='${PATHS.helper}';
const HONARTIK_ITICKET_PRETOKEN_RESULT_DIR='/var/lib/prhm-agent-selfmaint-exec/honartik-iticket-pretoken-prepare-v1';
const HONARTIK_ITICKET_PRETOKEN_RESULT=HONARTIK_ITICKET_PRETOKEN_RESULT_DIR+'/latest.json';
function applyHonartikIticketPretokenPrepareV1(){
  if(!fs.existsSync(HONARTIK_ITICKET_PRETOKEN_HELPER))throw new Error('honartik_iticket_pretoken_helper_missing');
  ensureDir(HONARTIK_ITICKET_PRETOKEN_RESULT_DIR,0o700);
  try{if(fs.existsSync(HONARTIK_ITICKET_PRETOKEN_RESULT))fs.unlinkSync(HONARTIK_ITICKET_PRETOKEN_RESULT)}catch{}
  const unit='prhm-honartik-iticket-pretoken-prepare-'+Date.now();
  const args=['--wait','--collect','--unit='+unit,'--property=Type=oneshot','--property=UMask=0077','--property=NoNewPrivileges=true','--property=PrivateTmp=true','--property=PrivateDevices=true','--property=ProtectSystem=strict','--property=ProtectHome=read-only','--property=ProtectKernelTunables=true','--property=ProtectKernelModules=true','--property=ProtectControlGroups=true','--property=RestrictAddressFamilies=AF_UNIX','--property=CapabilityBoundingSet=CAP_DAC_OVERRIDE','--property=AmbientCapabilities=','--property=RestrictNamespaces=true','--property=ReadWritePaths=/home/honartik/worktrees /home/honartik/domains/dashboard.honartik.ir/public_html/.git /home/honartik/git/honartik-dashboard-honartik-ir.git '+HONARTIK_ITICKET_PRETOKEN_RESULT_DIR,'--setenv=PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin','/usr/local/bin/prhm-node',HONARTIK_ITICKET_PRETOKEN_HELPER];
  cp.execFileSync('/usr/bin/systemd-run',args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:300000});
  if(!fs.existsSync(HONARTIK_ITICKET_PRETOKEN_RESULT))throw new Error('honartik_iticket_pretoken_result_missing');
  const result=readJson(HONARTIK_ITICKET_PRETOKEN_RESULT);
  if(result.ok!==true||result.schema_version!=='prhm.host-action-result.v1'||result.action!=='${ACTION}'||result.test_marker!=='ITICKET_EXTERNAL_PROVIDER_TEST=PASS'||result.origin_branch_verified!==true||result.worktree_application_mutation!==true||result.git_metadata_mutation!==true||result.production_application_tree_mutation!==false||result.database_mutation!==false||result.deploy!==false||result.external_network!==false||result.token_read!==false||result.rollback?.performed!==false)throw new Error('honartik_iticket_pretoken_result_invalid');
  return result;
}
`;}
function patchExecutor(source){
  if(source.includes("honartik_iticket_pretoken_prepare_v1:{operation:"))fail('executor_action_already_present');
  const specOld="  honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1:{operation:'host_action.honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1',kind:'honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1'},\n  host_action_v2_installer_v1:";
  const specNew="  honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1:{operation:'host_action.honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1',kind:'honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1'},\n  honartik_iticket_pretoken_prepare_v1:{operation:'host_action.honartik_iticket_pretoken_prepare_v1',kind:'honartik_iticket_pretoken_prepare_v1'},\n  host_action_v2_installer_v1:";
  let out=replaceOnce(source,specOld,specNew,'executor_spec');
  const marker='const IMOTION_CREDENTIAL_BIND_HELPER=';
  const idx=out.indexOf(marker);if(idx<0||out.indexOf(marker,idx+1)>=0)fail('anchor_mismatch:executor_block');out=out.slice(0,idx)+executorBlock()+out.slice(idx);
  const dispatchOld="if(action==='honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1')return applyHonartikIticketBatch2ResultBridgeHelperRefreshV1();if(action==='selfmaint_exec_route_refresh_v1')return applySelfmaintExecRouteRefreshV1();";
  const dispatchNew="if(action==='honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1')return applyHonartikIticketBatch2ResultBridgeHelperRefreshV1();if(action==='honartik_iticket_pretoken_prepare_v1')return applyHonartikIticketPretokenPrepareV1();if(action==='selfmaint_exec_route_refresh_v1')return applySelfmaintExecRouteRefreshV1();";
  out=replaceOnce(out,dispatchOld,dispatchNew,'executor_dispatch');
  return out;
}
function patchMcp(source){
  if(source.includes("'honartik_iticket_pretoken_prepare_v1'"))fail('mcp_action_already_present');
  return replaceOnce(source,"'honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1','host_action_v2_installer_v1'","'honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1','honartik_iticket_pretoken_prepare_v1','host_action_v2_installer_v1'",'mcp_enum');
}
function patchPolicy(source){
  const p=JSON.parse(source);if(!p.operations||!Array.isArray(p.typed_scopes))fail('policy_shape_invalid');if(p.operations[OPERATION]||p.typed_scopes.some(x=>x&&x.action===ACTION))fail('policy_action_already_present');if(!p.operations['host_action.honartik_iticket_dark_backend_batch2_result_bridge_helper_refresh_v1'])fail('policy_iticket_anchor_missing');
  p.operations[OPERATION]={level:3,risk:'high',one_time_use:true,requested_approver:'mohammad',expires_seconds:300,policy_version:POLICY_VERSION,rollback_reference:'host-action-v2:honartik-iticket-pretoken-prepare-v1:worktree-remove-branch-delete'};
  p.typed_scopes.push({tool:'host_action_v2_apply',project:'control_plane',environment:'production',action:ACTION,risk:'high',operation:OPERATION,principals:[{principal_id:'mohammad',roles:['mcp-operator']}]});
  return JSON.stringify(p,null,2)+'\n';
}
function helperBytes(){const b=Buffer.from(HELPER_B64,'base64');if(sha(b)!==HELPER_SHA)fail('helper_sha_mismatch');let s=b.toString('utf8');if(s.startsWith('#!'))s=s.slice(s.indexOf('\n')+1);new vm.Script(s);return b}
function read(file){const st=fs.lstatSync(file);if(!st.isFile()||st.isSymbolicLink())fail('unsafe_file:'+file);return fs.readFileSync(file)}
function verifyBaseline(){for(const k of Object.keys(BASELINE)){const actual=sha(read(PATHS[k]));if(actual!==BASELINE[k])fail('baseline_drift:'+k+':'+actual)}if(fs.existsSync(PATHS.helper))fail('helper_already_exists');helperBytes();return true}
function buildPatched(){verifyBaseline();return {base:Buffer.from(patchBase(read(PATHS.base).toString('utf8'))),executor:Buffer.from(patchExecutor(read(PATHS.executor).toString('utf8'))),mcp:Buffer.from(patchMcp(read(PATHS.mcp).toString('utf8'))),policy:Buffer.from(patchPolicy(read(PATHS.policy).toString('utf8'))),helper:helperBytes()}}
function preflight(){const p=buildPatched();return {ok:true,schema_version:'prhm.host-action-install-preflight.v1',action:ACTION,version:VERSION,preflight_only:true,baseline_match:true,helper_sha256:HELPER_SHA,candidate_sha256:Object.fromEntries(Object.entries(p).map(([k,v])=>[k,sha(v)])),control_plane_mutation:false,production_application_tree_mutation:false,database_mutation:false,deploy:false,external_network:false,token_read:false}}
function atomic(file,bytes,mode){fs.mkdirSync(path.dirname(file),{recursive:true,mode:0o755});const tmp=file+'.v17-'+process.pid+'-'+Date.now()+'.tmp';fs.writeFileSync(tmp,bytes,{mode,flag:'wx'});fs.renameSync(tmp,file);fs.chmodSync(file,mode)}
function run(bin,args,timeout=90000){return cp.execFileSync(bin,args,{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout}).trim()}
function restartAll(){for(const s of SERVICES)run('/usr/bin/systemctl',['restart',s],90000)}
function health(){for(const s of SERVICES)if(run('/usr/bin/systemctl',['is-active',s],30000)!=='active')fail('service_not_active:'+s)}
function install(){const patched=buildPatched();const stamp=new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14)+'-'+crypto.randomBytes(4).toString('hex');const dir=path.join(BACKUP_ROOT,stamp);fs.mkdirSync(dir,{recursive:false,mode:0o700});const old={};for(const k of ['base','executor','mcp','policy']){old[k]=read(PATHS[k]);fs.writeFileSync(path.join(dir,k+'.bak'),old[k],{mode:0o600,flag:'wx'})}let mutated=false;try{atomic(PATHS.helper,patched.helper,0o755);mutated=true;for(const k of ['base','executor','mcp','policy'])atomic(PATHS[k],patched[k],fs.statSync(PATHS[k]).mode&0o777);for(const k of ['base','executor','mcp'])run('/usr/local/bin/prhm-node',['--check',PATHS[k]],60000);JSON.parse(read(PATHS.policy).toString('utf8'));restartAll();health();const installed={};for(const k of ['base','executor','mcp','policy','helper'])installed[k]=sha(read(PATHS[k]));for(const k of ['base','executor','mcp'])if(!read(PATHS[k]).toString('utf8').includes(ACTION))fail('installed_action_missing:'+k);const policy=JSON.parse(read(PATHS.policy));if(policy.operations?.[OPERATION]?.level!==3||policy.operations?.[OPERATION]?.risk!=='high'||!policy.typed_scopes?.some(x=>x&&x.action===ACTION&&x.risk==='high'))fail('installed_policy_invalid');return {ok:true,schema_version:'prhm.host-action-install-result.v1',action:ACTION,version:VERSION,installed:true,helper_sha256:HELPER_SHA,installed_sha256:installed,backup_dir:dir,control_plane_mutation:true,production_application_tree_mutation:false,database_mutation:false,deploy:false,external_network:false,token_read:false,rollback:{performed:false}}}catch(e){if(mutated){try{for(const k of ['base','executor','mcp','policy'])atomic(PATHS[k],old[k],fs.statSync(PATHS[k]).mode&0o777);try{fs.unlinkSync(PATHS.helper)}catch{}restartAll();health()}catch(rb){throw new Error('install_failed_and_rollback_failed:'+String(e.message||e)+':'+String(rb.message||rb))}}throw new Error('install_failed_rolled_back:'+String(e.message||e))}}
if(require.main===module){try{const out=process.argv.includes('--preflight-only')?preflight():install();process.stdout.write(JSON.stringify(out)+'\n')}catch(e){process.stderr.write(String(e.stack||e)+'\n');process.exitCode=1}}
module.exports={ACTION,OPERATION,VERSION,POLICY_VERSION,PATHS,BASELINE,HELPER_SHA,patchBase,patchExecutor,patchMcp,patchPolicy,preflight,install};
